describe('PDF Upload and Display', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Adjust the URL to your application's upload page
    });

    it('should successfully upload a PDF and display it in the inline viewer', () => {
        const filePath = 'path/to/your/file.pdf'; // Adjust the file path to your test PDF

        cy.get('input[type="file"]').attachFile(filePath);
        cy.get('button[type="submit"]').click(); // Adjust the selector to your upload button

        cy.get('.pdf-viewer') // Adjust the selector to your PDF viewer
            .should('be.visible')
            .and('contain', 'PDF Loaded'); // Adjust based on your viewer's content
    });

    it('should show an error message when a non-PDF file is uploaded', () => {
        const filePath = 'path/to/your/file.txt'; // Adjust the file path to a non-PDF file

        cy.get('input[type="file"]').attachFile(filePath);
        cy.get('button[type="submit"]').click(); // Adjust the selector to your upload button

        cy.get('.error-message') // Adjust the selector to your error message
            .should('be.visible')
            .and('contain', 'Invalid file type. Please upload a PDF.'); // Adjust based on your error message
    });
});
